# Databricks notebook source
# MAGIC %md
# MAGIC # Identity Datalake — Phase 0 Tables
# MAGIC
# MAGIC Canonical identity spine: canonical identities, typed personas, provider
# MAGIC cross-references (with mapping history), the append-only resolution decision
# MAGIC log, steward decisions, merge/split impact, identity findings, ownership
# MAGIC relations and per-source health. IDs are generated by writers (no column
# MAGIC defaults). Idempotent: safe to re-run.

# COMMAND ----------

dbutils.widgets.text("catalog", "soc_platform", "Unity Catalog Name")
dbutils.widgets.text("schema", "agentic_soc", "Schema Name")

catalog = dbutils.widgets.get("catalog")
schema = dbutils.widgets.get("schema")

spark.sql(f"USE CATALOG `{catalog}`")
spark.sql(f"USE SCHEMA `{schema}`")

TBL = "USING DELTA TBLPROPERTIES ('delta.enableChangeDataFeed' = 'true', 'delta.autoOptimize.optimizeWrite' = 'true')"

# COMMAND ----------

DDL = {
    "identity_canonical": """
        canonical_id STRING NOT NULL,
        principal_type STRING NOT NULL,
        display_name STRING,
        account_count INT,
        providers ARRAY<STRING>,
        personas ARRAY<STRING>,
        normalized_states ARRAY<STRING>,
        state_conflict BOOLEAN,
        resolution_version STRING,
        resolver_version STRING,
        first_resolved_at TIMESTAMP,
        updated_at TIMESTAMP
    """,
    "identity_persona": """
        persona_id STRING NOT NULL,
        canonical_id STRING NOT NULL,
        persona_type STRING NOT NULL,
        account_count INT,
        resolution_version STRING,
        updated_at TIMESTAMP
    """,
    "identity_provider_xref": """
        account_key STRING NOT NULL,
        canonical_id STRING NOT NULL,
        persona_id STRING NOT NULL,
        provider STRING NOT NULL,
        tenant STRING NOT NULL,
        provider_object_id STRING NOT NULL,
        principal_type STRING,
        persona_type STRING,
        username STRING,
        upn STRING,
        email STRING,
        display_name STRING,
        employee_id STRING,
        provider_state STRING,
        normalized_state STRING,
        state_mapping_version STRING,
        owner STRING,
        grc_application_id STRING,
        runtime_host STRING,
        registration_source STRING,
        credential_fingerprint STRING,
        credential_expires_at STRING,
        last_seen STRING,
        source_status STRING,
        resolution_version STRING,
        valid_from TIMESTAMP,
        updated_at TIMESTAMP
    """,
    "identity_xref_history": """
        history_id STRING NOT NULL,
        account_key STRING NOT NULL,
        canonical_id STRING NOT NULL,
        persona_id STRING NOT NULL,
        resolution_version STRING NOT NULL,
        recorded_at TIMESTAMP
    """,
    "identity_resolution_decision": """
        decision_id STRING NOT NULL,
        left_key STRING NOT NULL,
        right_key STRING NOT NULL,
        rule STRING NOT NULL,
        verdict STRING NOT NULL,
        confidence DOUBLE,
        features STRING,
        resolver_version STRING,
        resolution_version STRING,
        decided_at TIMESTAMP
    """,
    "identity_steward_decision": """
        steward_decision_id STRING NOT NULL,
        review_of_decision_id STRING,
        left_key STRING NOT NULL,
        right_key STRING NOT NULL,
        verdict STRING NOT NULL,
        reviewer STRING NOT NULL,
        note STRING,
        decided_at TIMESTAMP
    """,
    "identity_resolution_impact": """
        impact_id STRING NOT NULL,
        kind STRING NOT NULL,
        superseded_canonical_id STRING,
        canonical_id STRING,
        account_keys ARRAY<STRING>,
        resolution_version STRING,
        recorded_at TIMESTAMP
    """,
    "identity_findings": """
        finding_id STRING NOT NULL,
        finding_type STRING NOT NULL,
        canonical_id STRING,
        account_key STRING,
        detail STRING,
        status STRING,
        first_seen TIMESTAMP,
        last_seen TIMESTAMP,
        resolution_version STRING
    """,
    "identity_relation": """
        relation_id STRING NOT NULL,
        source_id STRING NOT NULL,
        relation_type STRING NOT NULL,
        target_id STRING NOT NULL,
        provenance STRING,
        verification STRING,
        resolution_version STRING,
        updated_at TIMESTAMP
    """,
    "identity_source_health": """
        provider STRING NOT NULL,
        tenant STRING NOT NULL,
        snapshot_at STRING,
        snapshot_complete BOOLEAN,
        records_received BIGINT,
        records_accepted BIGINT,
        records_quarantined BIGINT,
        tombstoned BIGINT,
        stale BIGINT,
        status STRING,
        error_category STRING,
        last_run_at TIMESTAMP,
        last_success_at TIMESTAMP
    """,
}

for name, cols in DDL.items():
    spark.sql(f"CREATE TABLE IF NOT EXISTS {name} ({cols}) {TBL}")
    print(f"Ready: {name}")

dbutils.fs.mkdirs(f"/Volumes/{catalog}/{schema}/landing/identity")
print(f"Identity landing path: /Volumes/{catalog}/{schema}/landing/identity/<provider>/")
